package de.eldoria.bloodnight.generated;

import static de.eldoria.graph.std.runtime.Randoms.nextInt;
import static de.eldoria.graph.std.runtime.Switches.match;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Particle;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Skeleton;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class MagicSkeletonBehaviour implements CompiledBehaviour {
    private static final Particle CAMPFIRE_COSY_SMOKE = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:campfire_cosy_smoke");

    private static final PotionEffectType SLOWNESS = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:slowness");

    private static final PotionEffectType INSTANT_DAMAGE = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:instant_damage");

    private static final PotionEffectType LEVITATION = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:levitation");

    private static final PotionEffectType NAUSEA = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:nausea");

    private static final PotionEffectType WEAKNESS = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:weakness");

    private static final PotionEffectType POISON = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:poison");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final PotionEffectType NIGHT_VISION = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:night_vision");

    private final MobContext context;

    private Cooldown cooldown;

    public MagicSkeletonBehaviour(MobContext context) {
        this.context = context;
        // node #55 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onNightEnd() {
        // node #6 mob.night_end
        // node #8 world.spawn_particle
        // node #7 mob.self
        final Skeleton self = ((Skeleton) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), CAMPFIRE_COSY_SMOKE, self.getEyeLocation(), 30, 1.5d, 1.0d, 1.5d, null);
        // node #9
    }

    @Override
    public void onProjectileHit(ProjectileHitEvent event) {
        // node #33 event.projectile_hit
        // node #52 flow.branch
        // node #34 event.projectile_hit
        final Entity hitEntity = event.getHitEntity();
        if (!(hitEntity instanceof LivingEntity)) return;
        // node #51 flow.switch
        switch (match(nextInt(0, 7), 0, 1, 2, 3, 4, 5, 6, 7)) {
            case 0 -> {
                // node #36 living_entity.apply_effect
                // node #35 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(SLOWNESS, (int) (8.0d * 20), 1, true, true));
            }
            case 1 -> {
                // node #38 living_entity.apply_effect
                // node #37 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(SLOWNESS, (int) (6.0d * 20), 2, true, true));
            }
            case 2 -> {
                // node #40 living_entity.apply_effect
                // node #39 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(INSTANT_DAMAGE, (int) (2.0d * 20), 1, true, true));
            }
            case 3 -> {
                // node #42 living_entity.apply_effect
                // node #41 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(LEVITATION, (int) (5.0d * 20), 1, true, true));
            }
            case 4 -> {
                // node #44 living_entity.apply_effect
                // node #43 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(NAUSEA, (int) (5.0d * 20), 1, true, true));
            }
            case 5 -> {
                // node #46 living_entity.apply_effect
                // node #45 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(WEAKNESS, (int) (5.0d * 20), 1, true, true));
            }
            case 6 -> {
                // node #48 living_entity.apply_effect
                // node #47 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(POISON, (int) (6.0d * 20), 1, true, true));
            }
            case 7 -> {
                // node #50 living_entity.apply_effect
                // node #49 cast
                final LivingEntity cast = (hitEntity instanceof LivingEntity ? (LivingEntity) hitEntity : null);
                cast.addPotionEffect(new PotionEffect(POISON, (int) (4.0d * 20), 2, true, true));
            }
        }
        // node #53
    }

    @Override
    public void onTick() {
        // node #61 mob.tick
        // node #64 flow.branch
        // node #62 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(30000.0d));
        if (!cooldown) return;
        // node #63 living_entity.apply_effect
        ((Skeleton) this.context.entity()).addPotionEffect(new PotionEffect(NIGHT_VISION, (int) (60.0d * 20), 1, true, true));
        // node #65
    }
}
